import React, {useState} from "react";
import {useNavigate} from "react-router-dom";
import '../CSS/XtraBox.css';
import '../CSS/Global.css';

function XtraBox({title, description, children}) {

    const [popup, setPopup] = useState(false);

    return (
        <>
        <div className={"xtrabox-wrapper"}>
            <div className={"xtrabox-container"} onClick={() => setPopup(true)}>

                <div className={"xtrabox-title-container"}>
                    <div className={"xtrabox-title"}>
                        {title}
                    </div>
                </div>

                {description &&
                <div className={"xtrabox-body-container"}>
                    <div className={"xtrabox-body"}>
                        {description}
                    </div>
                </div>
                }
            </div>
        </div>
            {popup &&
                <>
                <div className="blur-overlay"></div>
                <div className={"xtrapopup-wrapper"}>

                    <div className={"xtrapopup-x-container"}>
                        <div className={"xtrapopup-x-container-1"}>
                            <div className={"xtrapopup-x-icon"} onClick={() => setPopup(false)}>
                                [ X ]
                            </div>
                        </div>
                    </div>

                    <div className={"xtrapopup-container"}>
                        {children}
                    </div>
                </div>
                </>
            }
        </>
    )
}

export default XtraBox;