import { useEffect } from "react";
import mermaid from "mermaid";

const MermaidDiagram = ({ chartDefinition }) => {

    useEffect(() => {
        mermaid.initialize({
            theme: "dark",
            startOnLoad: true });
        mermaid.contentLoaded();
    }, [chartDefinition]);

    return <div className="mermaid">{chartDefinition}</div>;
};

export default MermaidDiagram;