import React, {useState} from "react";
import {useNavigate} from "react-router-dom";
import '../CSS/XtraDrop.css';
import '../CSS/Global.css';

function XtraDrop({title, children}) {
    const [revealDrop, setReveal] = useState(true);

    return (
        !revealDrop ?
            <div className={"xtradrop-wrapper"}>
                <div className={"xtradrop-wrapper-1"}>
                    <div className={"xtradrop-container"}>

                        <div className={"xtradrop-icon-container"}>
                            <div className={"xtradrop-icon"} onClick={() => setReveal(true)}>
                                [ + ]
                            </div>
                        </div>

                        <div className={"xtradrop-title-container"}>
                            <div className={"xtradrop-title"}>
                                {title}
                            </div>
                        </div>
                    </div>
                </div>
                </div>
                :
            <div className={"xtradrop-wrapper"}>
                <div className={"xtradrop-wrapper-1"}>
                    <div className={"xtradrop-container"}>

                        <div className={"xtradrop-icon-container"}>
                            <div className={"xtradrop-icon"} onClick={() => setReveal(false)}>
                                [ - ]
                            </div>
                        </div>

                        <div className={"xtradrop-title-container"}>
                            <div className={"xtradrop-title"}>
                                {title}
                            </div>
                        </div>
                    </div>

                    <div className={"xtradrop-container-1"}>
                        <div className={"xtradrop-body-container"}>
                            <div className={"xtradrop-body"}>
                                {children}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
    )
}

                export default XtraDrop;