import React from 'react';
import {HashRouter as Router, Routes, Route, Navigate} from "react-router-dom";
import './App.css';
import Home from "./Components/Home";
import Contact from "./Components/Contact";
import About from "./Components/About";
import Qa from "./Components/Qa";
import Projex from "./Components/Projex";
import Xtra from "./Components/Xtra";


function App() {
  return (
        <Router>
            <Routes>
                {/*<Route path='/' element={<Home/>} />*/}
                <Route path="/" element={<Navigate to="/projex" replace />} />
                <Route path='/projex' element={<Projex/>} />
                <Route path='/projex/:page' element={<Projex/>} />
                <Route path='/xtra' element={<Xtra/>} />
                <Route path='/about' element={<About/>} />
                <Route path='/qa' element={<Qa/>} />
                <Route path='/contact' element={<Contact/>} />
            </Routes>
        </Router>
  );
}

export default App;
